document.addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Escape'){if(!$('#modal').hidden){closeModal();return}$$('.pane.selected').forEach(n=>n.classList.remove('selected'));window.getSelection()?.removeAllRanges();return}if(page!=='study')return;const input=e.target.closest('input,textarea,[contenteditable=true]');if(input)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='a'){const p=panes[focused];if(!p)return;const body=p.querySelector('.pane-content');if(!body)return;e.preventDefault();const sel=window.getSelection(),range=document.createRange();const turn=sel?.anchorNode?.parentElement?.closest('[data-turn]');const double=selectionPane===focused&&Date.now()-selectionAt<1500;range.selectNodeContents(focused==='question'&&turn&&!double?turn:body);sel.removeAllRanges();sel.addRange(range);selectionPane=focused;selectionAt=Date.now();return}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){if(focused==='video'&&video&&Number.isFinite(video.duration)){e.preventDefault();video.currentTime=Math.max(0,Math.min(video.duration,video.currentTime+(e.key==='ArrowRight'?15:-15)));following=true}else if(['slides','transcript','summary'].includes(focused)){e.preventDefault();pageMove(e.key==='ArrowRight'?1:-1)}}if(e.code==='Space'&&focused==='video'&&video){e.preventDefault();video.paused?video.play():video.pause()}});
