async function readPages(pages){const selected=pages.filter(p=>Number.isInteger(p)&&p>0&&p<=groups.length).slice(0,6);const result=[];for(const p of selected){const slide=groups[p-1].slide,cacheKey='vision-'+slide.id.replace(/[^a-zA-Z0-9_-]/g,'_')+'.json';let reading=visionCache.get(slide.url)||await saved(cacheKey,true);if(!reading||reading.url!==slide.url){const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('课件图片无法读取'));img.src=slide.local||resource(slide.url)});const ratio=Math.min(1,1280/img.naturalWidth,1280/img.naturalHeight),c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*ratio);c.height=Math.round(img.naturalHeight*ratio);c.getContext('2d').drawImage(img,0,0,c.width,c.height);let text='';await streamAI([{role:'user',content:[{type:'text',text:'准确读取这页课堂课件的文字、公式、图表与图示内容，保留知识结构。看不清的部分注明，不猜测，不描述无关版面位置。'},{type:'image_url',image_url:{url:c.toDataURL('image/jpeg',.8)}}]}],delta=>text+=delta,null,'deepseek-flash');reading={url:slide.url,text};visionCache.set(slide.url,reading);await save(cacheKey,reading,true)}result.push('[第 '+p+' 页 '+stamp(slide.t)+'] '+reading.text)}return result.join('\n\n')}
async function toggleSmartSkip(){if(skipEnabled){skipEnabled=false;renderTools();renderTranscript();return}if(!apiReady){toast('请先在课程问答中设置 API');return}if(!confirm('开启后会逐页分析课程转写，必要时读取课件，会产生额外 DeepSeek API 费用。会保留有用的讲解、例子、作业和课程安排。是否开启？'))return;skipEnabled=true;renderTools();await processSkip()}
async function processSkip(){if(skipBusy)return;skipBusy=true;const gen=lessonToken,end=lesson.end-lesson.start,complete=phase(lesson,Date.now()/1000)==='ended';skipRanges=untranscribedBoundaries(lines,end,complete,!lines.length);const indicator=el('div',{class:'skip-progress',style:'position:absolute;right:12px;bottom:14px;z-index:20;padding:8px 12px;border-radius:10px;background:#eff7ff;box-shadow:0 2px 8px #26385218;font-size:12px'},['正在处理 ',el('progress',{max:groups.length||1,value:0})]);$('#stage')?.append(indicator);try{for(let i=0;i<groups.length&&skipEnabled&&gen===lessonToken;i++){const group=groups[i],finish=groups[i+1]?.slide.t||end;if(!complete&&i===groups.length-1)break;const key='skip-'+courseKey(lesson)+'-'+group.slide.id.replace(/[^a-zA-Z0-9_-]/g,'_')+'.json';let decision=await saved(key,true);const version=JSON.stringify(group.lines.map(l=>[l.id,l.t,l.end,l.text]));if(!decision||decision.version!==version){let text='';const result=await streamAI([{role:'system',content:'识别课堂中确定无实质讲解的连续片段。只返回JSON：{"spans":[{"ids":["转写id"],"kind":"noise|break|chatter","confidence":0到1,"reason":"判断证据"}],"emptyPage":false,"confidence":0,"visual":"unknown"}。判断只针对杂音、课间无关闲聊、课前课后测试收音。保护知识讲解、课堂互动、实例、作业、考试、强调复述、课堂安排。不因内容少或语速慢而删除。ids必须是给定转写中连续的id。'},{role:'user',content:JSON.stringify(group.lines)}],chunk=>text+=chunk);const match=text.match(/\{[\s\S]*\}/);decision={data:JSON.parse(match?.[0]||text),version};await save(key,decision,true)}skipRanges=mergedSkipRanges(skipRanges.concat(conservativeRanges(group,finish,decision.data,true,false)),lines,complete);renderTranscript();if(video&&!video.paused){const next=automaticSkip(video.currentTime,video.duration,skipRanges);if(next)video.currentTime=next.end}indicator.querySelector('progress').value=i+1;}toast(skipRanges.length?'已识别 '+skipRanges.length+' 段无实质讲解':'未发现可放心跳过的片段')}catch(e){toast(e.message)}finally{skipBusy=false;indicator.remove();if(gen===lessonToken)renderTools()}}

